import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import API from '../../api/axios';
import toast from 'react-hot-toast';

export default function AdminLogin() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      // Ensure your backend companyRoutes has: router.post('/login', loginCompany);
      const { data } = await API.post('/companies/login', { email, password });
      
      // Store non-sensitive UI context (the secure token lives in the HttpOnly cookie)
      localStorage.setItem('adminInfo', JSON.stringify(data));
      
      toast.success(`Welcome back, ${data.name}`);
      navigate('/admin/checkout');
    } catch (error) {
      toast.error(error.response?.data?.message || 'Invalid admin credentials');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="w-full max-w-md p-8 bg-white rounded-2xl shadow-lg border border-gray-100 mx-auto mt-10">
      <div className="mb-6">
        <h2 className="text-2xl font-bold text-gray-900">POS Admin Portal</h2>
        <p className="text-sm text-gray-500 mt-1">Authenticate to manage terminals and link customer RFID cards.</p>
      </div>

      <form onSubmit={handleLogin} className="space-y-4">
        <div>
          <label className="block text-xs font-semibold uppercase tracking-wider text-gray-600 mb-1">Company Email</label>
          <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
            placeholder="management@futacafe.com"
            className="w-full px-4 py-2.5 bg-gray-50 border border-gray-300 rounded-lg text-gray-800 focus:outline-none focus:ring-2 focus:ring-gray-900 text-sm"
          />
        </div>

        <div>
          <label className="block text-xs font-semibold uppercase tracking-wider text-gray-600 mb-1">Administrator Password</label>
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            placeholder="••••••••"
            className="w-full px-4 py-2.5 bg-gray-50 border border-gray-300 rounded-lg text-gray-800 focus:outline-none focus:ring-2 focus:ring-gray-900 text-sm"
          />
        </div>

        <button
          type="submit"
          disabled={loading}
          className="w-full py-3 px-4 bg-gray-900 hover:bg-gray-800 text-white font-medium rounded-lg transition duration-200 disabled:opacity-50 shadow-sm text-sm mt-2"
        >
          {loading ? 'Authenticating...' : 'Sign In to Terminal'}
        </button>
      </form>
    </div>
  );
}
